// Opens a connection, asks it one question, and collects every frame until the pong that follows
// the ping sent right after the question: by then, everything the engine answered it with has
// arrived, and anything not present by the pong was not sent at all.
const askAndCollect = async (url: string, question: Record<string, unknown>): Promise<Frame[]> => {
