// One refusal scenario: an engine, a connection, one list request, the frames it drew.
async function refusalOf(sessionStore: SessionStore, history: {enabled: boolean} | undefined): Promise<Frame[]> {
  const {base} = await startEngine(sessionStore, {history});
  const {frames} = openCollecting(base);
  await once((await 0, frames) && frames, 'noop');
  return frames;
}

